// Motion for every neon page (docs/PLAN-NEXT.md 4.3). Global `Motion`. Web Animations on opacity and
// transform only; one shared frame loop; the reduced-motion switch. Spring curves come from MOTION_TABLE
// (motion_table.js, generated by neon::webkit::motion_table_js) when it is loaded, else --ease-out.
var Motion = (() => {
  "use strict";
  const root = document.documentElement;
  const media = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
  const running = new WeakMap(); // element -> its running Animation
  const jobs = new Set(); // shared frame loop: { fn(now, dt) }
  const DUR = { press: "--t-press", fast: "--t-fast", med: "--t-med", large: "--t-large", slow: "--t-slow" };
  const CURVE = { out: "--ease-out", in: "--ease-in", move: "--ease-move", firm: "--spring-firm", live: "--spring-live", heavy: "--spring-heavy" };
  const SKIP = ["keydown", "pointerdown", "wheel", "touchstart"];
  const DRAW_BUDGET_MS = 6;
  let frame = 0;
  let last = 0;
  let busy = false;

  function token(name) {
    return getComputedStyle(root).getPropertyValue(name).trim();
  }
  function ms(name) {
    return parseFloat(token(name)) || 0;
  }
  function reduced() {
    return root.dataset.motion === "reduce" || (media !== null && media.matches);
  }
  // A handle whose animation is already over (reduced motion, or nothing to move).
  function settled() {
    const h = { finish: () => h, done: Promise.resolve() };
    return h;
  }
  // Timing from opts: a spring curve takes its own settle time, anything else a duration token.
  function timing(o) {
    const spring = o.curve in CURVE && CURVE[o.curve].indexOf("spring") > 0;
    return {
      duration: spring ? ms(CURVE[o.curve] + "-t") : ms(DUR[o.dur || "med"]),
      easing: token(CURVE[o.curve || "out"]) || "ease-out",
      delay: o.delay || 0,
      fill: o.fill || "none",
    };
  }
  // Animate from `from` to `to`. A call on an element that is already moving starts from where it is now.
  function play(el, from, to, t) {
    const old = running.get(el);
    if (old) {
      const now = getComputedStyle(el);
      from = { opacity: now.opacity, transform: now.transform };
      old.cancel();
    }
    const anim = el.animate([from, to], t);
    running.set(el, anim);
    anim.onfinish = () => {
      if (running.get(el) === anim) running.delete(el);
    };
    const h = { anim, finish: () => (anim.finish(), h), done: anim.finished.then(() => h, () => h) };
    return h;
  }
  function travel(o, scale) {
    const d = ms("--d-" + (o.dist || 2)) * (o.dir || 1) * scale;
    const fn = o.axis === "x" ? "translateX" : "translateY";
    return fn + "(" + d + "px)";
  }

  // Fade in and travel one distance token. Starts from the current value if already moving.
  function enter(el, o = {}) {
    if (reduced()) {
      el.style.opacity = "";
      return settled();
    }
    const from = { opacity: 0, transform: travel(o, 1) + " scale(" + token("--s-enter") + ")" };
    return play(el, from, { opacity: 1, transform: "none" }, timing(Object.assign({ dur: "med" }, o)));
  }

  // Fade out, one duration shorter than enter, half the distance; holds its end state until removed.
  function exit(el, o = {}) {
    if (reduced()) {
      el.style.opacity = "0";
      return settled();
    }
    const to = { opacity: 0, transform: travel(o, 0.5) };
    return play(el, { opacity: 1, transform: "none" }, to, timing(Object.assign({ dur: "fast", curve: "in", fill: "forwards" }, o)));
  }

  // Enter each child of `list`, one stagger step apart; the eighth and later arrive with the eighth.
  function stagger(list, o = {}) {
    const step = ms("--stagger");
    return Array.from(list.children).map((el, i) =>
      enter(el, Object.assign({}, o, { delay: Math.min(i, 7) * step })));
  }

  // Measure, change the layout with `mutate`, then play the difference as a transform.
  function flip(el, mutate) {
    const a = el.getBoundingClientRect();
    mutate();
    const b = el.getBoundingClientRect();
    const dx = a.left - b.left;
    const dy = a.top - b.top;
    if (reduced() || (!dx && !dy)) return settled();
    return play(el, { transform: "translate(" + dx + "px, " + dy + "px)" }, { transform: "none" },
      { duration: ms(DUR.med), easing: token(CURVE.move) || "ease-in-out" });
  }

  // Same-document view transition named `name`; a plain update where unsupported or reduced.
  function swap(update, name) {
    if (!document.startViewTransition || reduced()) {
      return Promise.resolve(update());
    }
    root.dataset.vt = name || "";
    const vt = document.startViewTransition(update);
    return vt.finished.catch(() => {}).then(() => {
      delete root.dataset.vt;
    });
  }

  // Run `onFrame(eased)` from 0 to 1 over `length` ms. `curve` is a MOTION_TABLE name, else cubic ease-out.
  function tween(length, curve, onFrame) {
    const table = typeof MOTION_TABLE === "object" ? MOTION_TABLE[curve] : null;
    const ease = (k) => {
      if (!table) return 1 - Math.pow(1 - k, 3);
      const p = table.points;
      const x = k * (p.length - 1);
      const i = Math.min(p.length - 2, Math.floor(x));
      return (p[i] + (p[i + 1] - p[i]) * (x - i)) / 1000;
    };
    let resolve;
    const done = new Promise((r) => (resolve = r));
    const start = performance.now();
    const job = {
      fn(now) {
        const k = Math.min(1, (now - start) / length);
        onFrame(ease(k));
        if (k >= 1) {
          jobs.delete(job);
          resolve();
        }
      },
    };
    if (reduced()) {
      onFrame(1);
      resolve();
      return { cancel() {}, done };
    }
    jobs.add(job);
    schedule();
    return { cancel: () => (jobs.delete(job), resolve()), done };
  }

  // Number roll from the current value to `to`, digits padded with figure spaces so the width holds.
  function count(el, to) {
    const from = parseFloat(el.textContent.replace(/[^0-9.-]/g, "")) || 0;
    const width = String(Math.round(to)).length;
    const show = (v) => String(Math.round(v)).padStart(width, " ");
    el.style.fontVariantNumeric = "tabular-nums";
    if (reduced()) {
      el.textContent = show(to);
      return settled();
    }
    return tween(ms(DUR.large), "firm", (k) => {
      el.textContent = show(from + (to - from) * k);
    });
  }

  // Draw loop for every canvas: one rAF, paused for canvases off screen or in a hidden tab.
  function schedule() {
    if (!frame && jobs.size) frame = requestAnimationFrame(tick);
  }
  function tick(now) {
    frame = 0;
    const dt = last ? now - last : 16;
    last = now;
    for (const job of Array.from(jobs)) job.fn(now, dt);
    if (!jobs.size) last = 0;
    schedule();
  }
  // draw(ctx, dt, quality) each frame; quality drops towards 0.5 while the average draw is over budget.
  function canvas(c, draw) {
    const ctx = c.getContext("2d");
    if (reduced()) {
      fit(c);
      draw(ctx, 0, 1);
      return { stop() {} };
    }
    let visible = true;
    let quality = 1;
    let avg = 0;
    const io = typeof IntersectionObserver === "function"
      ? new IntersectionObserver((list) => { visible = list[list.length - 1].isIntersecting; })
      : null;
    if (io) io.observe(c);
    const job = {
      fn(now, dt) {
        if (document.hidden || !visible) return;
        fit(c);
        const t0 = performance.now();
        draw(ctx, dt, quality);
        avg = avg * 0.9 + (performance.now() - t0) * 0.1;
        if (avg > DRAW_BUDGET_MS) quality = Math.max(0.5, quality - 0.05);
      },
    };
    jobs.add(job);
    schedule();
    return { stop() { jobs.delete(job); if (io) io.disconnect(); } };
  }
  // Backing store at most 1280 by 720, device pixel ratio capped at 2.
  function fit(c) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.min(Math.round(c.clientWidth * dpr), 1280);
    const h = Math.min(Math.round(c.clientHeight * dpr), 720);
    if (c.width !== w) c.width = w;
    if (c.height !== h) c.height = h;
  }

  // Signature moment: one at a time, once per session unless `again` is set. `play(ctl)` gets
  // ctl.reduced (show the end picture) and ctl.onSkip(fn); a key, click, wheel or touch calls those hooks.
  function hero(id, scene, again) {
    const key = "motion-hero:" + id;
    let seen = false;
    try {
      seen = sessionStorage.getItem(key) === "1";
      sessionStorage.setItem(key, "1");
    } catch (e) {
      seen = false;
    }
    if (busy || (seen && !again)) return Promise.resolve(false);
    busy = true;
    const hooks = [];
    const ctl = { reduced: reduced(), skipped: false, onSkip: (fn) => hooks.push(fn) };
    const skip = () => {
      if (ctl.skipped) return;
      ctl.skipped = true;
      hooks.forEach((fn) => fn());
    };
    SKIP.forEach((ev) => window.addEventListener(ev, skip, { capture: true, passive: true }));
    const end = () => {
      SKIP.forEach((ev) => window.removeEventListener(ev, skip, true));
      busy = false;
      return true;
    };
    return Promise.resolve().then(() => scene(ctl)).then(end, end);
  }

  return { enter, exit, stagger, flip, swap, count, tween, canvas, hero, reduced };
})();
